mapper.select:
SELECT SHEETID,SHEETCODE,SHEETNAME,SHEETTARGET,CREATETIME,REALNAME,PROJECTID,AUDITDEST,ROWNUM RN FROM ( SELECT SHEET.SHEETID,SHEET.SHEETCODE,SHEET.SHEETNAME,SHEET.SHEETTARGET,SHEET.CREATETIME,CSTAFF.REALNAME,PROJECT.PROJECTID, NVL(ASTAFF.REALNAME,AORG.ORGNAME) AUDITDEST FROM TBL_NBSJ_SHEET SHEET LEFT JOIN TBL_STAFF CSTAFF ON SHEET.CREATESTAFF = CSTAFF.STAFFID LEFT JOIN TBL_NBSJ_PROJECT PROJECT ON SHEET.PROJECTID = PROJECT.PROJECTID LEFT JOIN TBL_STAFF ASTAFF ON PROJECT.AUDITSTAFFID = ASTAFF.STAFFID LEFT JOIN TBL_ORGANIZATION AORG ON AORG.ORGID = PROJECT.AUDITORGID
1=1 AND SHEET.PROJECTID = #{tBlNbsjSheetVo.projectId}
and SHEET.SHEETCODE like concat(concat('%',#{tBlNbsjSheetVo.sheetcode}),'%')
and SHEET.SHEETNAME like concat(concat('%',#{tBlNbsjSheetVo.sheetname}),'%')
AND SHEET.STATE = #{tBlNbsjSheetVo.state}
AND SHEET.auditStaffId = #{tBlNbsjSheetVo.auditStaffId}
)
